img {
  &[shrinktofit] {
    /* width of the document, minus the margin of the body (8px in the UA
    stylesheet), minus the scrollbar */
    max-inline-size: calc(100svi - 16px - env(scrollbar-inline-size)) !important;

    &[overflowing] {
      cursor: zoom-in;
      object-fit: scale-down;
    }
  }

  &[overflowing]:not([shrinktofit]) {
    cursor: zoom-out;
    /* Unbound the sizing of the image so it is displayed at full size. */
    block-size: auto !important;
    inline-size: auto !important;
    max-inline-size: none !important;
  }
